import { createBrowserRouter, Outlet, useLocation } from "react-router-dom";

import { ProtectedRoute } from "@legacy/components/ProtectedRoute";
import { MainLayout } from "@legacy/components/layout/MainLayout";
import { BarbaTransitionProvider } from "@legacy/components/transition/BarbaTransitionProvider";

import { Login } from "@legacy/pages/Login";
import NotFound from "@legacy/pages/NotFound";
import { AuthRedirect } from "@legacy/pages/AuthRedirect";

import { EnhancedDashboard } from "@features/dashboard/EnhancedDashboard";
import { ElectionsList } from "@features/elections/List";
import { ElectionDetails } from "@features/elections/Details";
import { GeoAreasDashboard } from "@features/geo-areas/Dashboard";
import { GeoAreaDetails } from "@features/geo-areas/Details";
import { VotersList } from "@features/voters/List";
import { VoterDetails } from "@features/voters/Details";
import { CandidatesList } from "@features/candidates/List";
import { CandidateDetails } from "@features/candidates/Details";
import { AgentsList } from "@features/agents/AgentsList";
import { VolunteersList } from "@features/volunteers/VolunteersList";
import { ZoneDashboard } from "@features/zones/ZoneDashboard";
import { CommitteesList } from "@features/committees/List";
import { CommitteeDetails } from "@features/committees/Details";
import { Settings } from "@features/settings/Settings";
import { ObservationsList } from "@features/observations/ObservationsList";
import { CampaignsList } from "@features/campaigns/CampaignsList";
import { AutomationDashboard } from "@features/automation/AutomationDashboard";
import FloatingLandingPage from "@features/marketing/pages/LandingPage";
import FloatingDashboard from "@features/marketing/pages/Dashboard";

const RouterShell = () => (
  <BarbaTransitionProvider>
    <Outlet />
  </BarbaTransitionProvider>
);

const MainLayoutWrapper = () => {
  const location = useLocation();
  const namespace = location.pathname.replace(/\//g, "-") || "app";

  return (
    <div
      data-barba="container"
      data-barba-namespace={namespace}
      className="min-h-screen"
    >
      <MainLayout />
    </div>
  );
};

const ComingSoon = ({ module }: { module: string }) => (
  <div className="glass-card text-center py-12">
    <h1 className="text-3xl font-bold text-gradient-primary mb-4">{module}</h1>
    <p className="text-muted-foreground">This module is under development</p>
  </div>
);

export const router = createBrowserRouter([
  {
    element: <RouterShell />,
    children: [
      { path: "/", element: <FloatingLandingPage /> },
      { path: "/experience", element: <FloatingDashboard /> },
      { path: "/app", element: <AuthRedirect /> },
      { path: "/login", element: <Login /> },
      {
        element: <ProtectedRoute />,
        children: [
          {
            element: <MainLayoutWrapper />,
            children: [
              { path: "/dashboard", element: <EnhancedDashboard /> },
              { path: "/elections", element: <ElectionsList /> },
              { path: "/elections/:id", element: <ElectionDetails /> },
              { path: "/geo-areas", element: <GeoAreasDashboard /> },
              { path: "/geo-areas/:id", element: <GeoAreaDetails /> },
              { path: "/committees", element: <CommitteesList /> },
              { path: "/committees/:id", element: <CommitteeDetails /> },
              { path: "/voters", element: <VotersList /> },
              { path: "/voters/:id", element: <VoterDetails /> },
              { path: "/candidates", element: <CandidatesList /> },
              { path: "/candidates/:id", element: <CandidateDetails /> },
              { path: "/agents", element: <AgentsList /> },
              { path: "/volunteers", element: <VolunteersList /> },
              { path: "/observations", element: <ObservationsList /> },
              { path: "/campaigns", element: <CampaignsList /> },
              { path: "/automation", element: <AutomationDashboard /> },
              {
                path: "/analytics",
                element: <ComingSoon module="Analytics" />,
              },
              { path: "/zones/mansoura", element: <ZoneDashboard /> },
              { path: "/settings", element: <Settings /> },
              { path: "*", element: <NotFound /> },
            ],
          },
        ],
      },
      { path: "*", element: <NotFound /> },
    ],
  },
]);

import { lazy, Suspense, useEffect, useMemo, useState } from "react";
import type { Feature, FeatureCollection, Point } from "geojson";
import { Filter, MapPin, RadioTower } from "lucide-react";
import { Card, CardContent, CardHeader, CardTitle } from "@shared/ui/card";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@shared/ui/select";
import { Badge } from "@shared/ui/badge";
import { Skeleton } from "@shared/ui/skeleton";
import { toast } from "sonner";
import { fetchCommitteeGeo, fetchRecentActivityGeo } from "../api";
import { getEcho } from "@shared/lib/echo";
import { Button } from "@shared/ui/button";

const LiveOperationsMapCanvas = lazy(() =>
  import("./LiveOperationsMapCanvas").then((module) => ({
    default: module.LiveOperationsMapCanvas,
  })),
);

const EMPTY_COLLECTION: FeatureCollection<Point, Record<string, any>> = {
  type: "FeatureCollection",
  features: [],
};

const isFeatureCollection = (
  value: unknown,
): value is FeatureCollection<Point, Record<string, any>> =>
  Boolean(
    value &&
      typeof value === "object" &&
      "type" in value &&
      (value as { type?: unknown }).type === "FeatureCollection" &&
      Array.isArray((value as { features?: unknown }).features),
  );

type FilterValue = "all" | string;

interface Filters {
  region: FilterValue;
  status: FilterValue;
  type: FilterValue;
}

const toFeature = (
  activity: Record<string, any>,
): Feature<Point, Record<string, any>> | null => {
  if (
    typeof activity.longitude !== "number" ||
    typeof activity.latitude !== "number"
  ) {
    return null;
  }

  return {
    type: "Feature",
    geometry: {
      type: "Point",
      coordinates: [activity.longitude, activity.latitude],
    },
    properties: {
      id: activity.id,
      type: activity.type,
      status: activity.status,
      support_score: activity.support_score,
      area_id: activity.area?.id ?? activity.area_id,
      area_name: activity.area?.name ?? activity.area_name,
      title: activity.title,
      reported_at: activity.reported_at,
    },
  };
};

const defaultFilters: Filters = {
  region: "all",
  status: "all",
  type: "all",
};

export const LiveOperationsMap = () => {
  const [committees, setCommittees] =
    useState<FeatureCollection<Point, Record<string, any>>>(EMPTY_COLLECTION);
  const [activities, setActivities] =
    useState<FeatureCollection<Point, Record<string, any>>>(EMPTY_COLLECTION);
  const [filters, setFilters] = useState<Filters>(defaultFilters);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    let isMounted = true;

    const load = async () => {
      setLoading(true);
      try {
        const [committeesGeo, activityGeo] = await Promise.all([
          fetchCommitteeGeo(),
          fetchRecentActivityGeo({ limit: 150 }),
        ]);

        if (!isMounted) return;

        setCommittees(
          isFeatureCollection(committeesGeo) ? committeesGeo : EMPTY_COLLECTION,
        );
        setActivities(
          isFeatureCollection(activityGeo) ? activityGeo : EMPTY_COLLECTION,
        );
      } catch (error) {
        console.error("Failed to load live operations map", error);
        toast.error("Unable to load map overlays.");
      } finally {
        if (isMounted) {
          setLoading(false);
        }
      }
    };

    load();

    return () => {
      isMounted = false;
    };
  }, []);

  useEffect(() => {
    const echo = getEcho();
    if (!echo) return;

    const channel = echo.channel("activities");

    const handler = (payload: { data: Record<string, any> }) => {
      const feature = toFeature(payload?.data ?? {});
      if (!feature) return;

      toast.success("New field report received", {
        description: feature.properties?.title ?? "Live update from the field.",
        duration: 4000,
      });

      setActivities((previous) => ({
        type: "FeatureCollection",
        features: [feature, ...previous.features].slice(0, 200),
      }));
    };

    channel.listen(".App\\Events\\ActivityCreated", handler);

    return () => {
      channel.stopListening(".App\\Events\\ActivityCreated", handler);
    };
  }, []);

  const filteredActivities = useMemo(() => {
    const filtered = activities.features.filter((feature) => {
      const props = feature.properties ?? {};
      if (
        filters.region !== "all" &&
        String(props.area_id) !== filters.region
      ) {
        return false;
      }
      if (filters.status !== "all" && props.status !== filters.status) {
        return false;
      }
      if (filters.type !== "all" && props.type !== filters.type) {
        return false;
      }
      return true;
    });

    return {
      type: "FeatureCollection",
      features: filtered,
    } as FeatureCollection<Point, Record<string, any>>;
  }, [activities, filters]);

  const regionOptions = useMemo(() => {
    const entries = new Map<string, string>();
    activities.features.forEach((feature) => {
      const areaId = feature.properties?.area_id;
      const areaName = feature.properties?.area_name;
      if (areaId && !entries.has(String(areaId))) {
        entries.set(String(areaId), areaName ?? `Region ${areaId}`);
      }
    });
    return Array.from(entries.entries());
  }, [activities]);

  const statusOptions = useMemo(() => {
    const statuses = new Set<string>();
    activities.features.forEach((feature) => {
      if (feature.properties?.status) {
        statuses.add(feature.properties.status);
      }
    });
    return Array.from(statuses.values());
  }, [activities]);

  const typeOptions = useMemo(() => {
    const types = new Set<string>();
    activities.features.forEach((feature) => {
      if (feature.properties?.type) {
        types.add(feature.properties.type);
      }
    });
    return Array.from(types.values());
  }, [activities]);

  const averageSupport = useMemo(() => {
    if (!filteredActivities.features.length) return 0;
    const total = filteredActivities.features.reduce((sum, feature) => {
      const support = feature.properties?.support_score ?? 0;
      return sum + Number(support || 0);
    }, 0);
    return total / filteredActivities.features.length;
  }, [filteredActivities]);

  return (
    <Card className="glass-card">
      <CardHeader className="flex flex-col gap-2 md:flex-row md:items-center md:justify-between">
        <div className="flex items-center gap-3">
          <RadioTower className="h-5 w-5 text-primary" />
          <div>
            <CardTitle className="text-xl">Live field operations</CardTitle>
            <p className="text-sm text-muted-foreground">
              Monitor committees and real-time field intelligence across Egypt.
            </p>
          </div>
        </div>
        <div className="flex flex-wrap items-center gap-2 text-xs text-muted-foreground">
          <Badge variant="outline">
            {filteredActivities.features.length} active signals
          </Badge>
          <Badge variant="secondary">
            Avg. support {averageSupport.toFixed(1)}%
          </Badge>
        </div>
      </CardHeader>
      <CardContent className="space-y-4">
        <div className="grid gap-3 md:grid-cols-4">
          <div className="flex items-center gap-2">
            <Filter className="h-4 w-4 text-primary" />
            <span className="text-sm font-medium text-muted-foreground">
              Filters
            </span>
          </div>
          <Select
            value={filters.region}
            onValueChange={(value) =>
              setFilters((prev) => ({ ...prev, region: value }))
            }
          >
            <SelectTrigger>
              <SelectValue placeholder="Region" />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="all">All regions</SelectItem>
              {regionOptions.map(([id, name]) => (
                <SelectItem key={id} value={id}>
                  {name}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>

          <Select
            value={filters.type}
            onValueChange={(value) =>
              setFilters((prev) => ({ ...prev, type: value }))
            }
          >
            <SelectTrigger>
              <SelectValue placeholder="Activity type" />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="all">All types</SelectItem>
              {typeOptions.map((type) => (
                <SelectItem key={type} value={type}>
                  {type}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>

          <Select
            value={filters.status}
            onValueChange={(value) =>
              setFilters((prev) => ({ ...prev, status: value }))
            }
          >
            <SelectTrigger>
              <SelectValue placeholder="Status" />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="all">All statuses</SelectItem>
              {statusOptions.map((status) => (
                <SelectItem key={status} value={status}>
                  {status}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>

          <Button
            variant="ghost"
            size="sm"
            onClick={() => setFilters(defaultFilters)}
          >
            Reset
          </Button>
        </div>

        <Suspense
          fallback={
            <div className="flex flex-col items-center justify-center h-[480px] rounded-xl border border-dashed border-muted">
              <MapPin className="h-8 w-8 text-muted-foreground mb-2" />
              <p className="text-sm text-muted-foreground">
                Loading map overlays…
              </p>
              <Skeleton className="h-[280px] w-3/4 mt-4" />
            </div>
          }
        >
          {loading ? (
            <div className="flex flex-col items-center justify-center h-[480px] rounded-xl border border-dashed border-muted">
              <MapPin className="h-8 w-8 text-muted-foreground mb-2" />
              <p className="text-sm text-muted-foreground">
                Preparing map layers…
              </p>
              <Skeleton className="h-[280px] w-3/4 mt-4" />
            </div>
          ) : (
            <LiveOperationsMapCanvas
              committees={committees}
              activities={filteredActivities}
            />
          )}
        </Suspense>

        <div className="flex flex-wrap items-center gap-4 text-xs text-muted-foreground">
          <div className="flex items-center gap-2">
            <span className="inline-block h-3 w-12 rounded-full bg-gradient-to-r from-green-300 via-orange-300 to-red-400" />
            <span>
              Heat intensity represents support level & turnout pressure.
            </span>
          </div>
          <div className="flex items-center gap-2">
            <span className="inline-block h-2 w-2 rounded-full bg-primary" />
            <span>Committee locations</span>
          </div>
        </div>
      </CardContent>
    </Card>
  );
};

export default LiveOperationsMap;

import { memo, useEffect, useMemo, useRef } from "react";
import {
  MapContainer,
  TileLayer,
  Marker,
  Popup,
  useMapEvents,
} from "react-leaflet";
import type { FeatureCollection, Feature, Point } from "geojson";
import L, { LatLngExpression } from "leaflet";
import "leaflet/dist/leaflet.css";
import "@shared/vendor/leaflet-heat-stub";

import markerIcon2x from "leaflet/dist/images/marker-icon-2x.png";
import markerIcon from "leaflet/dist/images/marker-icon.png";
import markerShadow from "leaflet/dist/images/marker-shadow.png";

// Fix default marker icons when bundling with Vite
delete (L.Icon.Default.prototype as any)._getIconUrl;
L.Icon.Default.mergeOptions({
  iconRetinaUrl: markerIcon2x,
  iconUrl: markerIcon,
  shadowUrl: markerShadow,
});

interface LiveOperationsMapCanvasProps {
  committees: FeatureCollection<Point, Record<string, any>>;
  activities: FeatureCollection<Point, Record<string, any>>;
}

const DEFAULT_CENTER: LatLngExpression = [30.0444, 31.2357];

const extractHeatPoints = (
  featureCollection: FeatureCollection<Point, Record<string, any>>,
): [number, number, number][] =>
  featureCollection.features
    .map((feature: Feature<Point, Record<string, any>>) => {
      const [lng, lat] = feature.geometry.coordinates;
      const weight =
        typeof feature.properties?.support_score === "number"
          ? Math.max(0.1, feature.properties.support_score / 100)
          : 0.4;
      return [lat, lng, weight] as [number, number, number];
    })
    .filter(
      (point): point is [number, number, number] =>
        Number.isFinite(point[0]) && Number.isFinite(point[1]),
    );

// Map hook to capture map instance
const MapHandler = ({ onMapReady }: { onMapReady: (map: L.Map) => void }) => {
  const map = useMapEvents({});
  useEffect(() => {
    onMapReady(map);
  }, [map, onMapReady]);
  return null;
};

export const LiveOperationsMapCanvas = memo(
  ({ committees, activities }: LiveOperationsMapCanvasProps) => {
    const mapRef = useRef<L.Map | null>(null);
    const heatRef = useRef<any | null>(null);

    const heatPoints = useMemo(
      () => extractHeatPoints(activities),
      [activities],
    );

    useEffect(() => {
      const map = mapRef.current;
      if (!map) return;

      if (heatRef.current) {
        heatRef.current.remove();
        heatRef.current = null;
      }

      if (!heatPoints.length) {
        return;
      }

      heatRef.current = (L as any)
        .heatLayer(heatPoints, {
          radius: 28,
          blur: 20,
          maxZoom: 12,
          minOpacity: 0.35,
        })
        .addTo(map);
    }, [heatPoints]);

    useEffect(() => {
      const map = mapRef.current;
      if (!map) return;

      if (!heatPoints.length && !committees.features.length) {
        return;
      }

      const bounds = L.latLngBounds([]);

      heatPoints.forEach(([lat, lng]) => bounds.extend([lat, lng]));
      committees.features.forEach((feature) => {
        const [lng, lat] = feature.geometry.coordinates;
        bounds.extend([lat, lng]);
      });

      if (bounds.isValid()) {
        map.fitBounds(bounds.pad(0.2));
      }
    }, [heatPoints, committees]);

    return (
      <MapContainer
        className="h-[480px] w-full rounded-xl"
        center={DEFAULT_CENTER}
        zoom={6}
      >
        <MapHandler
          onMapReady={(map) => {
            mapRef.current = map;
          }}
        />
        <TileLayer
          attribution='&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'
          url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
        />

        {committees.features.map((feature) => {
          const [lng, lat] = feature.geometry.coordinates;
          const properties = feature.properties ?? {};

          return (
            <Marker
              key={properties.id ?? `${lat}-${lng}`}
              position={[lat, lng]}
            >
              <Popup>
                <div className="space-y-1">
                  <p className="font-semibold text-sm">{properties.name}</p>
                  {properties.geo_area && (
                    <p className="text-xs text-muted-foreground">
                      {properties.geo_area}
                    </p>
                  )}
                  <p className="text-xs">
                    Agents: {properties.agents_count ?? 0}
                  </p>
                  <p className="text-xs">
                    Voters: {properties.voters_count ?? 0}
                  </p>
                </div>
              </Popup>
            </Marker>
          );
        })}
      </MapContainer>
    );
  },
);

LiveOperationsMapCanvas.displayName = "LiveOperationsMapCanvas";

export default LiveOperationsMapCanvas;

import { render, screen, waitFor } from "@testing-library/react";
import { QueryClient, QueryClientProvider } from "@tanstack/react-query";
import { BrowserRouter } from "react-router-dom";
import { vi } from "vitest";
import { ElectionsList } from "../List";
import { LanguageProvider } from "@shared/contexts/LanguageContext";
import { fetchElections } from "../api";

vi.mock("../api", () => ({
  fetchElections: vi.fn(),
  deleteElection: vi.fn(),
  createElection: vi.fn(),
  updateElection: vi.fn(),
}));

beforeEach(() => {
  vi.clearAllMocks();
});

test("renders election list", async () => {
  vi.mocked(fetchElections).mockResolvedValueOnce({
    data: [
      {
        id: "1",
        name: "Election A",
        type: "presidential",
        status: "draft",
        start_date: "2024-01-01",
        end_date: "2024-01-02",
      },
    ],
    total: 1,
  });

  const qc = new QueryClient();
  render(
    <QueryClientProvider client={qc}>
      <LanguageProvider>
        <BrowserRouter>
          <ElectionsList />
        </BrowserRouter>
      </LanguageProvider>
    </QueryClientProvider>,
  );
  await waitFor(() =>
    expect(screen.getByText("Election A")).toBeInTheDocument(),
  );
});

test("handles undefined data", async () => {
  vi.mocked(fetchElections).mockResolvedValueOnce({
    data: undefined as any,
    total: 0,
  });

  const qc = new QueryClient();
  render(
    <QueryClientProvider client={qc}>
      <LanguageProvider>
        <BrowserRouter>
          <ElectionsList />
        </BrowserRouter>
      </LanguageProvider>
    </QueryClientProvider>,
  );

  await waitFor(() => expect(screen.getByText(/No data/i)).toBeInTheDocument());
});

import { useState, useEffect } from "react";
import { motion } from "framer-motion";
import { useTranslation } from "react-i18next";
import { useForm } from "react-hook-form";
import { MapPin, X, Loader2 } from "lucide-react";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
} from "@shared/ui/dialog";
import { Button } from "@shared/ui/button";
import { Input } from "@shared/ui/input";
import { Label } from "@shared/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@shared/ui/select";
import { useLanguage } from "@shared/contexts/LanguageContext";
import { GeoArea, GeoAreaFormData } from "./types";
import { createGeoArea, updateGeoArea } from "./api";

interface GeoAreaFormProps {
  isOpen: boolean;
  onClose: () => void;
  onSuccess: () => void;
  area?: GeoArea | null;
  parentAreas: GeoArea[];
}

const areaTypes = ["governorate", "district", "city", "village"] as const;

export const GeoAreaForm = ({
  isOpen,
  onClose,
  onSuccess,
  area,
  parentAreas,
}: GeoAreaFormProps) => {
  const { t } = useTranslation();
  const { direction } = useLanguage();
  const [isSubmitting, setIsSubmitting] = useState(false);

  const {
    register,
    handleSubmit,
    setValue,
    watch,
    reset,
    formState: { errors },
  } = useForm<GeoAreaFormData>({
    defaultValues: {
      name: "",
      parent_id: null,
      type: "city",
    },
  });

  const selectedType = watch("type");
  const selectedParentId = watch("parent_id");

  // Filter available parent areas based on hierarchy
  const getAvailableParents = () => {
    if (selectedType === "governorate") return [];
    if (selectedType === "district") {
      return parentAreas.filter((p) => p.type === "governorate");
    }
    if (selectedType === "city") {
      return parentAreas.filter(
        (p) => p.type === "governorate" || p.type === "district",
      );
    }
    if (selectedType === "village") {
      return parentAreas.filter(
        (p) => p.type === "city" || p.type === "district",
      );
    }
    return parentAreas;
  };

  useEffect(() => {
    if (area) {
      // Edit mode
      setValue("name", area.name);
      setValue("parent_id", area.parent_id);
      setValue("type", area.type);
    } else {
      // Add mode
      reset();
    }
  }, [area, setValue, reset]);

  const onSubmit = async (data: GeoAreaFormData) => {
    try {
      setIsSubmitting(true);

      if (area) {
        await updateGeoArea(area.id, data);
      } else {
        await createGeoArea(data);
      }

      onSuccess();
    } catch (error) {
      console.error("Failed to save geo area:", error);
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleClose = () => {
    reset();
    onClose();
  };

  return (
    <Dialog open={isOpen} onOpenChange={handleClose}>
      <DialogContent className="glass-card border-white/20 max-w-md">
        <DialogHeader>
          <DialogTitle className="text-xl font-semibold text-gradient-primary flex items-center gap-2">
            <MapPin className="h-5 w-5" />
            {area ? t("common.edit") : t("geo_areas.add_area")}
          </DialogTitle>
        </DialogHeader>

        <motion.form
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          onSubmit={handleSubmit(onSubmit)}
          className="space-y-6"
        >
          {/* Area Name */}
          <div className="space-y-2">
            <Label htmlFor="name" className="text-sm font-medium">
              {t("geo_areas.area_name")} *
            </Label>
            <Input
              id="name"
              {...register("name", {
                required: "Area name is required",
                minLength: {
                  value: 2,
                  message: "Area name must be at least 2 characters",
                },
              })}
              placeholder={t("geo_areas.area_name")}
              className="glass border-white/20"
              dir={direction}
            />
            {errors.name && (
              <motion.p
                initial={{ opacity: 0, y: -10 }}
                animate={{ opacity: 1, y: 0 }}
                className="text-destructive text-xs"
              >
                {errors.name.message}
              </motion.p>
            )}
          </div>

          {/* Area Type */}
          <div className="space-y-2">
            <Label className="text-sm font-medium">
              {t("geo_areas.area_type")} *
            </Label>
            <Select
              value={selectedType}
              onValueChange={(value) => {
                setValue("type", value as any);
                // Reset parent selection when type changes
                setValue("parent_id", null);
              }}
            >
              <SelectTrigger className="glass border-white/20">
                <SelectValue placeholder={t("geo_areas.area_type")} />
              </SelectTrigger>
              <SelectContent className="glass-card border-white/20 bg-background/95 backdrop-blur-md z-50">
                {areaTypes.map((type) => (
                  <SelectItem key={type} value={type}>
                    {t(`geo_areas.types.${type}`)}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>

          {/* Parent Area */}
          {getAvailableParents().length > 0 && (
            <div className="space-y-2">
              <Label className="text-sm font-medium">
                {t("geo_areas.parent_area")}
                {selectedType !== "governorate" && " *"}
              </Label>
              <Select
                value={selectedParentId || ""}
                onValueChange={(value) => setValue("parent_id", value || null)}
              >
                <SelectTrigger className="glass border-white/20">
                  <SelectValue placeholder={t("geo_areas.parent_area")} />
                </SelectTrigger>
                <SelectContent className="glass-card border-white/20 bg-background/95 backdrop-blur-md z-50">
                  {getAvailableParents().map((parent) => (
                    <SelectItem key={parent.id} value={parent.id}>
                      {parent.name} ({t(`geo_areas.types.${parent.type}`)})
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
          )}

          {/* Hierarchy Info */}
          {selectedType && getAvailableParents().length > 0 && (
            <motion.div
              initial={{ opacity: 0, height: 0 }}
              animate={{ opacity: 1, height: "auto" }}
              className="p-3 bg-primary/5 rounded-lg border border-primary/20"
            >
              <p className="text-xs text-muted-foreground">
                <strong>Hierarchy:</strong>{" "}
                {t(`geo_areas.types.${selectedType}`)}
                {selectedType !== "governorate" && " requires a parent area"}
              </p>
            </motion.div>
          )}

          {/* Actions */}
          <div className="flex gap-3 pt-4 border-t border-white/10">
            <Button
              type="button"
              variant="outline"
              onClick={handleClose}
              disabled={isSubmitting}
              className="flex-1 glass-button"
            >
              {t("common.cancel")}
            </Button>
            <Button
              type="submit"
              disabled={isSubmitting}
              className="flex-1 bg-gradient-primary text-white shadow-glow disabled:opacity-50"
            >
              {isSubmitting ? (
                <>
                  <Loader2 className="h-4 w-4 mr-2 animate-spin" />
                  {t("common.loading")}
                </>
              ) : (
                t("common.save")
              )}
            </Button>
          </div>
        </motion.form>
      </DialogContent>
    </Dialog>
  );
};

