import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useState,
  ReactNode,
} from "react";
import api, { setAuthToken } from "@shared/lib/api";

export interface Role {
  id?: number | string;
  name: string;
  guard_name?: string;
  [key: string]: unknown;
}

export interface User {
  id: number | string;
  name: string;
  email: string;
  roles?: Role[];
  roleNames?: string[];
  [key: string]: unknown;
}

export interface LoginData {
  email: string;
  password: string;
  remember?: boolean;
}

export interface RegisterData {
  name: string;
  email: string;
  password: string;
  password_confirmation?: string;
  [key: string]: unknown;
}

interface AuthContextType {
  user: User | null;
  isAuthenticated: boolean;
  loading: boolean;
  login: (credentials: LoginData) => Promise<void>;
  register: (data: RegisterData) => Promise<void>;
  logout: () => Promise<void>;
  refresh: () => Promise<void>;
}

const TOKEN_STORAGE_KEY = "token";

const AuthContext = createContext<AuthContextType | undefined>(undefined);

const getStoredToken = () =>
  typeof window !== "undefined"
    ? localStorage.getItem(TOKEN_STORAGE_KEY)
    : null;

const persistToken = (token: string | null) => {
  if (typeof window === "undefined") {
    return;
  }

  if (token) {
    localStorage.setItem(TOKEN_STORAGE_KEY, token);
  } else {
    localStorage.removeItem(TOKEN_STORAGE_KEY);
  }
};

const extractToken = (payload: unknown): string | null => {
  if (!payload || typeof payload !== "object") {
    return null;
  }

  const candidate =
    (payload as Record<string, unknown>).token ||
    (payload as Record<string, unknown>).access_token ||
    (payload as Record<string, unknown>).authToken ||
    (payload as Record<string, unknown>).data;

  if (typeof candidate === "string") {
    return candidate;
  }

  if (candidate && typeof candidate === "object") {
    return (
      ((candidate as Record<string, unknown>).token as string | undefined) ??
      ((candidate as Record<string, unknown>).access_token as
        | string
        | undefined) ??
      null
    );
  }

  return null;
};

const normalizeUser = (payload: unknown): User => {
  const raw =
    (payload as Record<string, unknown>)?.data ??
    (payload as Record<string, unknown>)?.user ??
    payload;

  if (!raw || typeof raw !== "object") {
    throw new Error("Invalid user payload received from API");
  }

  const rawRoles = Array.isArray((raw as Record<string, unknown>).roles)
    ? ((raw as Record<string, unknown>).roles as Role[])
    : [];

  const roles = rawRoles.map((role) => ({
    ...role,
    name: String(role?.name ?? role),
  }));

  return {
    ...(raw as Record<string, unknown>),
    roles,
    roleNames: roles.map((role) => role.name),
  } as User;
};

export const useAuthContext = () => {
  const ctx = useContext(AuthContext);
  if (!ctx) {
    throw new Error("useAuthContext must be used within AuthProvider");
  }
  return ctx;
};

interface AuthProviderProps {
  children: ReactNode;
}

export const AuthProvider = ({ children }: AuthProviderProps) => {
  const [user, setUser] = useState<User | null>(null);
  const [loading, setLoading] = useState(true);

  const clearSession = useCallback(() => {
    setUser(null);
    persistToken(null);
    setAuthToken(null);
  }, []);

  const bootstrapUser = useCallback(
    async (token?: string | null) => {
      const activeToken = token ?? getStoredToken();

      if (!activeToken) {
        clearSession();
        return;
      }

      setAuthToken(activeToken);

      try {
        const response = await api.get("/api/v1/me");
        const nextUser = normalizeUser(response.data);
        setUser(nextUser);
      } catch (error) {
        console.error("Failed to fetch authenticated user", error);
        clearSession();
        throw error;
      }
    },
    [clearSession],
  );

  const login = useCallback(
    async (credentials: LoginData) => {
      setLoading(true);
      try {
        const response = await api.post("/api/v1/login", credentials);
        const token = extractToken(response.data);
        if (token) {
          setAuthToken(token);
          persistToken(token);
        }

        const nextUser = normalizeUser(response.data);
        setUser(nextUser);

        if (!token) {
          await bootstrapUser();
        }
      } catch (error) {
        clearSession();
        throw error;
      } finally {
        setLoading(false);
      }
    },
    [bootstrapUser, clearSession],
  );

  const register = useCallback(
    async (data: RegisterData) => {
      setLoading(true);
      try {
        const response = await api.post("/api/v1/register", data);
        const token = extractToken(response.data);

        if (token) {
          setAuthToken(token);
          persistToken(token);
        }

        const nextUser = normalizeUser(response.data);
        setUser(nextUser);

        if (!token) {
          await bootstrapUser();
        }
      } catch (error) {
        clearSession();
        throw error;
      } finally {
        setLoading(false);
      }
    },
    [bootstrapUser, clearSession],
  );

  const logout = useCallback(async () => {
    setLoading(true);
    try {
      await api.post("/api/v1/logout");
    } catch (error) {
      console.warn("Failed to call logout endpoint", error);
    } finally {
      clearSession();
      setLoading(false);
    }
  }, [clearSession]);

  const refresh = useCallback(async () => {
    setLoading(true);
    try {
      await bootstrapUser();
    } finally {
      setLoading(false);
    }
  }, [bootstrapUser]);

  useEffect(() => {
    const initialize = async () => {
      try {
        await bootstrapUser();
      } finally {
        setLoading(false);
      }
    };

    void initialize();
  }, [bootstrapUser]);

  const value = useMemo<AuthContextType>(
    () => ({
      user,
      isAuthenticated: Boolean(user),
      loading,
      login,
      register,
      logout,
      refresh,
    }),
    [loading, login, logout, refresh, register, user],
  );

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
};

export const useAuth = () => useAuthContext();

export default AuthContext;

import {
  createContext,
  useContext,
  useEffect,
  useMemo,
  useState,
  ReactNode,
} from "react";
import { useTranslation } from "react-i18next";

type Language = "ar" | "en";
type Direction = "rtl" | "ltr";

interface LanguageContextType {
  language: Language;
  direction: Direction;
  toggleLanguage: () => void;
  setLanguage: (lang: Language) => void;
  t: (key: string, options?: Record<string, unknown>) => string;
}

const LanguageContext = createContext<LanguageContextType | undefined>(
  undefined,
);

export const useLanguage = () => {
  const context = useContext(LanguageContext);
  if (!context) {
    throw new Error("useLanguage must be used within LanguageProvider");
  }
  return context;
};

interface LanguageProviderProps {
  children: ReactNode;
}

export const LanguageProvider = ({ children }: LanguageProviderProps) => {
  const { i18n, t } = useTranslation();
  const [language, setLanguageState] = useState<Language>(() => {
    if (typeof window === "undefined") {
      return "ar";
    }

    const stored = window.localStorage.getItem("language");
    return (stored as Language) || "ar";
  });

  const direction = useMemo<Direction>(
    () => (language === "ar" ? "rtl" : "ltr"),
    [language],
  );

  const toggleLanguage = () => {
    setLanguageState((prev) => (prev === "ar" ? "en" : "ar"));
  };

  const setLanguage = (newLang: Language) => {
    setLanguageState(newLang);
  };

  useEffect(() => {
    i18n.changeLanguage(language);
  }, [i18n, language]);

  useEffect(() => {
    if (typeof document === "undefined") {
      return;
    }

    document.dir = direction;
    document.documentElement.lang = language;

    const body = document.body;
    if (!body) {
      return;
    }

    body.dataset.direction = direction;
    body.classList.toggle("is-rtl", direction === "rtl");
    body.classList.toggle("is-ltr", direction === "ltr");
  }, [direction, language]);

  useEffect(() => {
    if (typeof window === "undefined") {
      return;
    }

    window.localStorage.setItem("language", language);
  }, [language]);

  const value = useMemo(
    () => ({
      language,
      direction,
      toggleLanguage,
      setLanguage,
      t,
    }),
    [direction, language, t],
  );

  return (
    <LanguageContext.Provider value={value}>
      {children}
    </LanguageContext.Provider>
  );
};

import {
  createContext,
  ReactNode,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useState,
} from "react";
import { request } from "@shared/lib/api";
import { getEcho } from "@shared/lib/echo";
import { toast } from "sonner";

export type NotificationType = "performance" | "field" | "risk" | "other";

export interface NotificationItem {
  id: number;
  type: NotificationType;
  category: string;
  title: string;
  message: string;
  priority: "low" | "medium" | "high";
  meta: Record<string, unknown>;
  read_at: string | null;
  created_at: string;
  created_ago?: string;
  is_high_priority?: boolean;
}

type NotificationFilter = "all" | NotificationType;

interface NotificationContextValue {
  notifications: NotificationItem[];
  filteredNotifications: NotificationItem[];
  unreadCount: number;
  loading: boolean;
  filter: NotificationFilter;
  setFilter: (filter: NotificationFilter) => void;
  markAsRead: (id: number) => Promise<void>;
  markAllAsRead: () => Promise<void>;
  refresh: () => Promise<void>;
  isDrawerOpen: boolean;
  setDrawerOpen: (open: boolean) => void;
}

const NotificationContext = createContext<NotificationContextValue | undefined>(
  undefined,
);

interface PaginatedNotificationResponse {
  data: NotificationItem[];
}

export const NotificationProvider = ({ children }: { children: ReactNode }) => {
  const [notifications, setNotifications] = useState<NotificationItem[]>([]);
  const [loading, setLoading] = useState(false);
  const [filter, setFilter] = useState<NotificationFilter>("all");
  const [isDrawerOpen, setDrawerOpen] = useState(false);

  const fetchNotifications = useCallback(
    async ({ showLoader = true, suppressToasts = false } = {}) => {
      if (showLoader) {
        setLoading(true);
      }
      try {
        const response = await request<PaginatedNotificationResponse>({
          url: "/notifications",
          method: "get",
          params: {
            per_page: 50,
          },
        });

        const incoming = [...(response.data ?? [])].sort(
          (a, b) =>
            new Date(b.created_at).getTime() - new Date(a.created_at).getTime(),
        );

        setNotifications((previous) => {
          const previousIds = new Set(previous.map((item) => item.id));
          const newItems = incoming.filter((item) => !previousIds.has(item.id));

          if (!suppressToasts) {
            newItems
              .filter((item) => item.priority === "high")
              .forEach((item) => {
                toast(item.title, {
                  description: item.message,
                });
              });
          }

          return incoming;
        });
      } catch (error) {
        console.error("Failed to load notifications", error);
      } finally {
        if (showLoader) {
          setLoading(false);
        }
      }
    },
    [],
  );

  const prependNotification = useCallback((incoming: NotificationItem) => {
    setNotifications((prev) => {
      const existing = prev.filter((item) => item.id !== incoming.id);
      const next = [incoming, ...existing];
      return next.sort(
        (a, b) =>
          new Date(b.created_at).getTime() - new Date(a.created_at).getTime(),
      );
    });
  }, []);

  useEffect(() => {
    fetchNotifications({ showLoader: true, suppressToasts: true });
  }, [fetchNotifications]);

  useEffect(() => {
    const interval = window.setInterval(() => {
      fetchNotifications({ showLoader: false, suppressToasts: false });
    }, 60000);

    return () => window.clearInterval(interval);
  }, [fetchNotifications]);

  useEffect(() => {
    const echo = getEcho();
    if (!echo) return;

    const channel = echo.channel("notifications");
    const handler = (payload: { data: NotificationItem }) => {
      const notification = payload.data;
      prependNotification(notification);

      if (notification.priority === "high") {
        toast(notification.title, {
          description: notification.message,
        });
      }
    };

    channel.listen(".App\\Events\\NotificationCreated", handler);

    return () => {
      channel.stopListening(".App\\Events\\NotificationCreated", handler);
    };
  }, [prependNotification]);

  const markAsRead = useCallback(async (id: number) => {
    await request<{ data: NotificationItem }>({
      url: `/notifications/${id}/read`,
      method: "patch",
    });

    setNotifications((prev) =>
      prev.map((notification) =>
        notification.id === id
          ? { ...notification, read_at: new Date().toISOString() }
          : notification,
      ),
    );
  }, []);

  const markAllAsRead = useCallback(async () => {
    await request({
      url: "/notifications/read-all",
      method: "post",
    });

    setNotifications((prev) =>
      prev.map((notification) => ({
        ...notification,
        read_at: new Date().toISOString(),
      })),
    );
  }, []);

  const filteredNotifications = useMemo(() => {
    if (filter === "all") return notifications;
    return notifications.filter((notification) => notification.type === filter);
  }, [filter, notifications]);

  const unreadCount = useMemo(
    () => notifications.filter((notification) => !notification.read_at).length,
    [notifications],
  );

  const value: NotificationContextValue = {
    notifications,
    filteredNotifications,
    unreadCount,
    loading,
    filter,
    setFilter,
    markAsRead,
    markAllAsRead,
    refresh: () =>
      fetchNotifications({ showLoader: true, suppressToasts: true }),
    isDrawerOpen,
    setDrawerOpen,
  };

  return (
    <NotificationContext.Provider value={value}>
      {children}
    </NotificationContext.Provider>
  );
};

export const useNotifications = (): NotificationContextValue => {
  const context = useContext(NotificationContext);
  if (!context) {
    throw new Error(
      "useNotifications must be used within a NotificationProvider",
    );
  }

  return context;
};

import {
  createContext,
  useContext,
  useEffect,
  useMemo,
  useState,
  ReactNode,
} from "react";

type Theme = "light" | "dark";

interface ThemeContextType {
  theme: Theme;
  toggleTheme: () => void;
  setTheme: (theme: Theme) => void;
}

const ThemeContext = createContext<ThemeContextType | undefined>(undefined);

export const useTheme = () => {
  const context = useContext(ThemeContext);
  if (!context) {
    throw new Error("useTheme must be used within ThemeProvider");
  }
  return context;
};

interface ThemeProviderProps {
  children: ReactNode;
}

export const ThemeProvider = ({ children }: ThemeProviderProps) => {
  const [theme, setThemeState] = useState<Theme>(() => {
    if (typeof window === "undefined") {
      return "light";
    }

    const stored = window.localStorage.getItem("theme");
    return (stored as Theme) || "light";
  });

  const toggleTheme = () => {
    setThemeState((prev) => (prev === "light" ? "dark" : "light"));
  };

  const setTheme = (newTheme: Theme) => {
    setThemeState(newTheme);
  };

  useEffect(() => {
    if (typeof document === "undefined") {
      return;
    }

    const root = document.documentElement;
    root.classList.remove("light", "dark");
    root.classList.add(theme);
    document.body.dataset.theme = theme;
  }, [theme]);

  useEffect(() => {
    if (typeof window === "undefined") {
      return;
    }

    window.localStorage.setItem("theme", theme);
  }, [theme]);

  const value = useMemo(
    () => ({
      theme,
      toggleTheme,
      setTheme,
    }),
    [theme],
  );

  return (
    <ThemeContext.Provider value={value}>{children}</ThemeContext.Provider>
  );
};

import axios, {
  AxiosInstance,
  AxiosRequestConfig,
  AxiosResponse,
  InternalAxiosRequestConfig,
} from "axios";
import { useState, useCallback, useEffect, useRef } from "react";

let authToken: string | null = null;

export const setAuthToken = (token: string | null) => {
  authToken = token;

  if (token) {
    api.defaults.headers.common = api.defaults.headers.common || {};
    api.defaults.headers.common.Authorization = `Bearer ${token}`;
  } else if (api.defaults.headers.common) {
    delete (api.defaults.headers.common as Record<string, unknown>)
      .Authorization;
  }
};

const rawBaseURL =
  import.meta.env.VITE_API_URL || "http://127.0.0.1:8000/api/v1";

const { resolvedBaseURL, apiPrefix } = (() => {
  try {
    const parsed = new URL(rawBaseURL);
    return {
      resolvedBaseURL: parsed.origin,
      apiPrefix: parsed.pathname.replace(/\/+$/, ""),
    };
  } catch (error) {
    return {
      resolvedBaseURL: rawBaseURL,
      apiPrefix: "",
    };
  }
})();

const api: AxiosInstance = axios.create({
  baseURL: resolvedBaseURL,
  headers: {
    Accept: "application/json",
  },
});

axios.defaults.baseURL = rawBaseURL;
axios.defaults.headers.common = axios.defaults.headers.common || {};
axios.defaults.headers.common.Accept = "application/json";

const ensureLeadingSlash = (value: string) =>
  value.startsWith("/") ? value : `/${value}`;

const joinWithPrefix = (suffix: string) => {
  const normalizedPrefix = ensureLeadingSlash(apiPrefix);
  const sanitizedSuffix = suffix.startsWith("/") ? suffix.slice(1) : suffix;
  return `${normalizedPrefix}/${sanitizedSuffix}`.replace(/\/{2,}/g, "/");
};

const normalizeUrl = (url?: string) => {
  if (!url || /^https?:\/\//i.test(url) || !apiPrefix) {
    return url;
  }

  const normalizedPrefix = ensureLeadingSlash(apiPrefix);

  if (url.startsWith("/")) {
    if (url.startsWith(normalizedPrefix)) {
      return url;
    }
    return joinWithPrefix(url.slice(1));
  }

  return joinWithPrefix(url);
};

const withAuthorizationHeader = <
  T extends AxiosRequestConfig | InternalAxiosRequestConfig,
>(
  config: T,
): T => {
  const token =
    authToken ||
    (typeof window !== "undefined" ? localStorage.getItem("token") : null);

  if (token) {
    config.headers = config.headers || {};
    (config.headers as Record<string, unknown>).Authorization =
      `Bearer ${token}`;
  } else if (config.headers && "Authorization" in config.headers) {
    delete (config.headers as Record<string, unknown>).Authorization;
  }

  return config;
};

axios.interceptors.request.use(withAuthorizationHeader);
api.interceptors.request.use(withAuthorizationHeader);

api.interceptors.response.use(
  (response) => response,
  (error) => Promise.reject(error),
);

type CacheEntry<T> = { expiry: number; data: T };
const cache = new Map<string, CacheEntry<any>>();
const DEFAULT_TTL = 5 * 60 * 1000;

export function clearCache() {
  cache.clear();
}

export async function request<T = unknown>(
  config: AxiosRequestConfig,
  { useCache = false, ttl = DEFAULT_TTL } = {},
): Promise<T> {
  const normalizedConfig: AxiosRequestConfig = {
    ...config,
    url: normalizeUrl(config.url),
  };

  const key = JSON.stringify({
    url: normalizedConfig.url,
    method: normalizedConfig.method,
    params: normalizedConfig.params,
    data: normalizedConfig.data,
  });

  if (useCache) {
    const cached = cache.get(key);
    if (cached && cached.expiry > Date.now()) {
      return cached.data;
    }
  }

  const response: AxiosResponse<T> = await api.request<T>(normalizedConfig);

  if (useCache) {
    cache.set(key, { data: response.data, expiry: Date.now() + ttl });
  }

  return response.data;
}

export function useApi<T = unknown>(
  config: AxiosRequestConfig,
  options: { useCache?: boolean; ttl?: number } = {},
) {
  const configRef = useRef(config);
  const optionsRef = useRef(options);

  useEffect(() => {
    configRef.current = config;
  }, [config]);

  useEffect(() => {
    optionsRef.current = options;
  }, [options]);

  const [data, setData] = useState<T | null>(null);
  const [error, setError] = useState<Error | null>(null);
  const [loading, setLoading] = useState(false);

  const execute = useCallback(async (overrideConfig?: AxiosRequestConfig) => {
    setLoading(true);
    setError(null);
    try {
      const baseConfig = configRef.current;
      const finalConfig = { ...baseConfig, ...overrideConfig };
      const result = await request<T>(finalConfig, optionsRef.current);
      setData(result);
      return result;
    } catch (err) {
      setError(err as Error);
      throw err;
    } finally {
      setLoading(false);
    }
  }, []);

  return { data, error, loading, execute };
}

export default api;

/**
 * Safe data handling utilities for robust React applications
 */

// Enhanced safe array utility
export function safeArray<T>(value?: T[] | null | undefined): T[] {
  return Array.isArray(value) ? value : [];
}

// Safe object utility
export function safeObject<T>(value?: T | null | undefined): T | {} {
  return value && typeof value === "object" ? value : ({} as T);
}

// Safe number utility
export function safeNumber(value?: number | string | null): number {
  const num = Number(value);
  return isNaN(num) ? 0 : num;
}

// Safe string utility
export function safeString(value?: string | null | undefined): string {
  return typeof value === "string" ? value : "";
}

// Type guard for arrays
export function isValidArray<T>(value: unknown): value is T[] {
  return Array.isArray(value) && value.length > 0;
}

// Type guard for objects
export function isValidObject(
  value: unknown,
): value is Record<string, unknown> {
  return value !== null && typeof value === "object" && !Array.isArray(value);
}

// Safe data mapper with fallback
export function safeMap<T, U>(
  data: T[] | null | undefined,
  mapper: (item: T, index: number) => U,
  fallback: U[] = [],
): U[] {
  const safeData = safeArray(data);
  if (safeData.length === 0) return fallback;

  try {
    return safeData.map(mapper);
  } catch (error) {
    console.warn("Safe map failed:", error);
    return fallback;
  }
}

// Safe data filter with error handling
export function safeFilter<T>(
  data: T[] | null | undefined,
  predicate: (item: T, index: number) => boolean,
): T[] {
  const safeData = safeArray(data);

  try {
    return safeData.filter(predicate);
  } catch (error) {
    console.warn("Safe filter failed:", error);
    return [];
  }
}

// Safe data reducer with error handling
export function safeReduce<T, U>(
  data: T[] | null | undefined,
  reducer: (acc: U, current: T, index: number) => U,
  initialValue: U,
): U {
  const safeData = safeArray(data);

  try {
    return safeData.reduce(reducer, initialValue);
  } catch (error) {
    console.warn("Safe reduce failed:", error);
    return initialValue;
  }
}

// API response wrapper
export interface SafeApiResponse<T> {
  data: T[];
  total: number;
  page?: number;
  loading: boolean;
  error: string | null;
}

// Safe API response handler
export function createSafeApiResponse<T>(
  response?: { data?: T[]; total?: number; page?: number } | null,
  loading = false,
  error: string | null = null,
): SafeApiResponse<T> {
  return {
    data: safeArray(response?.data),
    total: safeNumber(response?.total),
    page: response?.page || 1,
    loading,
    error,
  };
}

